// === Tab: mySketch ===
let walkers = [], points = [], pointSubsets = [], subsetColors = []; 
const npoints = 24, nsubsets = 3, subsetSize = Math.floor(npoints / nsubsets);
const kernel = "thin-plate";
let myShader;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	pixelDensity(1);
	myShader = createShader(vert, frag);
	generate();
}

function mouseClicked() {
	generate()
}

function generate () {
	const A = -0.2, B = 1.2;
	for (let i = 0; i < npoints; i++) {
		walkers [i] = new RandomWalker (createVector(random(A,B)*width, random(A,B)*height), {
			avgStep:2, angleDev:0.5,
			xmin : width * A, xmax : width * B,
			ymin : height * A, ymax : height * B,
		});
		points [i] = [0,0]
	}
	let k = 0;
	for (let i = 0; i < nsubsets; i++) {
		pointSubsets [i] = [];
		for (let j = 0; j < subsetSize; j++) {
			pointSubsets [i][j] = points[k++]
		}
		subsetColors [i] = [random(),random(),random()];
	}
}

function movePoints() {
	for (let i = 0; i < npoints; i++) {
		const w = walkers[i];
		const p = w.walk();
		points[i][0] = p.x;
		points[i][1] = p.y;
	} 
}

function computeRBF (points) {
	const [w, h] = [width, height];
	const D = 2;
	let anchors = [
		[-w * D, -h * D],
		[-w * D, h * (D+1)],
		[w * (D+1), h * (D+1)],
		[w * (D+1), -h * D], 
		...points
	];
	const V = -1000;
	let values = [V, V, V, V]
	for (let i = 0; i < points.length; i++) values.push(0)
	return {rbf: RBF(anchors, values, kernel), anchors, values};
}

function draw() {
	blendMode(BLEND)
	background(0);
	translate(-width/2,-height/2);
	movePoints();
	blendMode(EXCLUSION);
	shader (myShader);
	for (let i = 0; i < nsubsets; i++) { 
		let {rbf, anchors, values} = computeRBF(pointSubsets[i]);
		myShader.setUniform('u_height', height);
		myShader.setUniform('u_npts', anchors.length);
		myShader.setUniform('u_color', subsetColors[i]);
		myShader.setUniform('u_pts', anchors.flat());
		myShader.setUniform('u_weights', rbf.w);
		myShader.setUniform('u_epsilon', rbf.epsilon);
		noStroke();
		rect(0,0,width,height);
		//computeImage();
		//image (img, 0, 0, img.width*cellSize, img.height*cellSize)
	}
	resetShader();
	blendMode (BLEND);
	fill ('white');	
	for (let p of points) {
		let [x,y] = p;
		circle (x, y, 10)
	}
}

// === Tab: RBF ===
/**
 * This is essentially the rbf module by Thibaut Séguy, but modified to use a selectable norm
 * See https://github.com/thibauts/rbf
 **/
let RBF;

{
	const euclideanNorm = (pa, pb) => {
    return numeric.norm2(numeric.sub(pb, pa));
  }

  const distanceLinear = (r) => {
    return r;
  }

  const distanceCubic = (r) => {
    return Math.pow(r, 3);
  }

  const distanceQuintic = (r) => {
    return Math.pow(r, 5);
  }

  const distanceThinPlate = (r) => {
    if(r === 0) return 0;
    return Math.pow(r, 2) * Math.log(r);
  }

  const distanceGaussian = (r, epsilon) => {
    return Math.exp(- Math.pow(r / epsilon, 2));
  }

  const distanceInverseMultiquadric = (r, epsilon) => {
    return 1.0 / Math.sqrt(Math.pow(r / epsilon, 2) + 1);
  }

  const distanceMultiquadric = (r, epsilon) => {
    return Math.sqrt(Math.pow(r / epsilon, 2) + 1);
  }

	const distanceFunctions = {
    'linear': distanceLinear,
    'cubic':  distanceCubic,
    'quintic': distanceQuintic,
    'thin-plate': distanceThinPlate,
    'gaussian': distanceGaussian,
    'inverse-multiquadric': distanceInverseMultiquadric,
    'multiquadric': distanceMultiquadric
  };


	RBF = (points, values, distanceFunction, epsilon, norm = euclideanNorm) => {

		let distance;
		if(distanceFunction) {
      distance = typeof distanceFunction !== 'string' ? distanceFunction 
        : distanceFunctions[distanceFunction];
    } 
		else {
			distance = distanceFunctions.linear;
		}

		let M = numeric.identity(points.length);

		// First compute the point to point distance matrix
    // to allow computing epsilon if it's not provided
    for(let j=0; j<points.length; j++) {
      for(let i=0; i<points.length; i++) {
        M[j][i] = norm(points[i], points[j]);
      }
    }

		// if needed, compute espilon as the average distance between points
    if(epsilon === undefined) {
      epsilon = numeric.sum(M) / (Math.pow(points.length, 2) - points.length);
    }

		// update the matrix to reflect the requested distance function
    for(let j=0; j<points.length; j++) {
      for(let i=0; i<points.length; i++) {
        M[j][i] = distance(M[j][i], epsilon);
      }
    }

		  // determine dimensionality of target values
    let sample = values[0];
    var D = typeof sample === 'number' ? 1 : sample.length;

		// generalize to vector values
    if(typeof sample === 'number') {
      values = values.map(function(value) {
        return [value];
      });
    }

		// reshape values by component
    let tmp = new Array(D);
    for(let i=0; i<D; i++) {
      tmp[i] = values.map((value) => value[i]);
    }
    values = tmp;

		// Compute basis functions weights by solving
    // the linear system of equations for each target component
    var w = new Array(D);
    let LU = numeric.LU(M);
    for(let i=0; i<D; i++) {
      w[i] = numeric.LUsolve(LU, values[i]);
    }

		// The returned interpolant will compute the value at any point 
    // by summing the weighted contributions of the input points
    const interpolant = function (p) {

      let distances = new Array(points.length);
      for(let i=0; i < points.length; i++) {
        distances[i] = distance(norm(p, points[i]), epsilon);
      }

      let sums = new Array(D);
      for(let i=0; i<D; i++) {
        sums[i] = numeric.sum(numeric.mul(distances, w[i]));
      }

      return sums;
    }

		interpolant.w = w.flat();
		interpolant.epsilon = epsilon;
		return interpolant;

	}
}


// === Tab: shader ===
const kernelGLSL = {
	  'linear': 'return r;',
    'cubic':  'return r*r*r;',
    'quintic': 'return pow(r,5.);',
    'thin-plate': 'if (r == 0.0) return 0.0; return  r * r * log(r);',
    'gaussian': 'return exp(-pow(r / u_epsilon, 2.));',
    'inverse-multiquadric': 'return 1.0 / sqrt(pow(r / u_epsilon, 2.) + 1.);',
    'multiquadric': 'return sqrt(pow(r / u_epsilon, 2.) + 1.);',
}

const vert = `#version 300 es 

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

 in vec3 aPosition;
 in vec2 aTexCoord;

out vec2 vTexCoord;

void main() {
  	gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);  
		vTexCoord = aTexCoord;
}`;

const frag = `#version 300 es
precision highp float;
#define MAXPOINTS 50
uniform float u_height;
uniform vec2 u_pts[MAXPOINTS];
uniform float u_weights[MAXPOINTS];
uniform int u_npts;
uniform float u_epsilon;
uniform vec3 u_color;

float kernel (float r) {
	${kernelGLSL[kernel]}
}

float rbf (vec2 coord) {
	float sum = 0.;
	for (int i = 0; i < MAXPOINTS; i++) {
	  if (i == u_npts) break;
		float r = length(coord - u_pts[i]);
		sum += kernel(r)*u_weights[i];
	}
	return sum;
}

out vec4 fragColor;

void main() {
	if (rbf (vec2(gl_FragCoord.x, u_height - gl_FragCoord.y)) < 0.0) discard;
	else fragColor = vec4(u_color, 0.5);
}`;


// === Tab: randomWalker ===
class RandomWalker {
	constructor (seed, {avgStep=1, 
										 stepRange=0.4,   // maintain step within 40 % of average
										 stepDev = 5,     // Std dev for step variation
										 angleDev = 5,			// Std dev for angle variation
										 xmin = -Infinity, ymin = -Infinity,
										 xmax = Infinity, ymax = Infinity
										} = {}) {
		Object.assign(this,{ang:random(TAU),p:seed.copy(),avgStep,stepRange,stepDev,angleDev,xmin,xmax,ymin,ymax})
	}
	walk () {
		let {p,ang,avgStep,stepRange,stepDev,angleDev} = this;
		let s = constrain(randomGaussian(avgStep,stepDev),avgStep*(1-stepRange),avgStep*(1+stepRange));
		let v = createVector (s,0).rotate(ang);
		p.add(v);
		p.x = constrain(p.x, this.xmin, this.xmax);
		p.y = constrain(p.y, this.ymin, this.ymax);
		this.ang += randomGaussian(0,angleDev) / PI;
		return p;
	}
}

